Here's a C++ function that returns the largest element of an array:

```c++
#include <iostream>
#include <vector>

using namespace std;

int largestElement(vector<int>& arr) {
    int max = arr[0];
    for (int I = 1; I < arr.size(); i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

int main() {
    vector<int> arr = {10, 20, 30, 40, 50};
    int largest = largestElement(arr);
    cout << "The largest element in the array is: " << largest << endl;
    return 0;
}
```

This function takes an array `arr` as input and returns the largest element in the array. It first initializes a variable `max` to the first element of the array, and then loops through the array, comparing each element with `max` and updating `max` if it is greater. Finally, it returns the largest element.

